INSERT INTO `ems_movies` (`id`, `title`, `original_title`, `description`, `genre`, `duration`, `age_rating`, `release_date`, `director`, `cast`, `language`, `country`, `poster_url`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Avatar: Dòng Chảy Của Nước', 'Avatar: The Way of Water', 'Hơn một thập kỷ sau sự kiện của phần phim đầu tiên, Jake Sully và Neytiri đã xây dựng gia đình tại Pandora nhưng mối đe dọa từ người Trái Đất quay trở lại.', 'Khoa học viễn tưởng, Hành động, Phiêu lưu', 192, 'T13', '2022-12-16', 'James Cameron', 'Sam Worthington, Zoe Saldana, Sigourney Weaver, Stephen Lang', 'Tiếng Anh - Phụ đề & Lồng tiếng', 'Mỹ', 'https://images.unsplash.com/photo-1536440136628-849c177e76a1?w=500', 'now_showing', '2026-10-06 06:53:12', '2026-10-06 06:53:12'),
(2, 'Mai', 'Mai', 'Câu chuyện cảm động về cuộc đời của Mai - một người phụ nữ làm nghề massage trị liệu và tình yêu đầy trắc trở với chàng nhạc công Dương.', 'Tâm lý, Tình cảm', 131, 'T18', '2024-02-10', 'Trấn Thành', 'Phương Anh Đào, Tuấn Trần, Trấn Thành, Hồng Đào', 'Tiếng Việt', 'Việt Nam', 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?w=500', 'now_showing', '2026-10-06 06:53:12', '2026-10-06 06:53:12'),
(3, 'Dune: Hành Tinh Cát - Phần 2', 'Dune: Part Two', 'Paul Atreides hợp lực cùng Chani và tộc Fremen để trả thù những kẻ đã hủy hoại gia tộc mình, đồng thời đối mặt với số phận vũ trụ.', 'Khoa học viễn tưởng, Sử thi, Hành động', 166, 'T16', '2024-03-01', 'Denis Villeneuve', 'Timothée Chalamet, Zendaya, Rebecca Ferguson, Javier Bardem', 'Tiếng Anh - Phụ đề Việt', 'Mỹ', 'https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=500', 'now_showing', '2026-10-06 06:53:12', '2026-10-06 06:53:12'),
(4, 'Hố Đen Tử Thần', 'Interstellar', 'Trong tương lai Trái Đất bị tàn phá, một nhóm phi hành gia du hành qua lỗ sâu gần Sao Thổ để tìm kiếm hành tinh mới cho nhân loại.', 'Khoa học viễn tưởng, Phiêu lưu, Kịch tính', 169, 'T13', '2014-11-07', 'Christopher Nolan', 'Matthew McConaughey, Anne Hathaway, Jessica Chastain, Michael Caine', 'Tiếng Anh - Phụ đề Việt (Bản IMAX Remaster)', 'Mỹ', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=500', 'now_showing', '2026-10-06 06:53:12', '2026-10-06 06:53:12'),
(5, 'Deadpool & Wolverine', 'Deadpool & Wolverine', 'Wade Wilson bị lôi kéo vào nhiệm vụ giải cứu đa vũ trụ và buộc phải đồng hành cùng dị nhân Wolverine cộc cằn.', 'Hành động, Siêu anh hùng, Hài hước', 128, 'T18', '2024-07-26', 'Shawn Levy', 'Ryan Reynolds, Hugh Jackman, Emma Corrin, Matthew Macfadyen', 'Tiếng Anh - Phụ đề Việt', 'Mỹ', 'https://images.unsplash.com/photo-1578836537282-3171d77f8632?w=500', 'now_showing', '2026-10-06 06:53:12', '2026-10-06 06:53:12'),
(6, 'Quật Mộ Trùng Ma', 'Exhuma', 'Hai pháp sư, một chuyên gia phong thủy và một người làm nghề mai táng dính vào lời nguyền kinh hoàng khi khai quật một ngôi mộ bí ẩn.', 'Kinh dị, Bí ẩn, Huyền bí', 134, 'T16', '2024-03-15', 'Jang Jae-hyun', 'Choi Min-sik, Kim Go-eun, Yoo Hae-jin, Lee Do-hyun', 'Tiếng Hàn - Phụ đề Việt', 'Hàn Quốc', 'https://images.unsplash.com/photo-1509198397868-475647b2a1e5?w=500', 'now_showing', '2026-10-06 06:53:12', '2026-10-06 06:53:12');
