(2, 'target_audience', 'Phù hợp đối tượng khán giả mục tiêu', 'Nội dung phù hợp nhóm khách hàng trọng tâm của Aurora Cinema.', 2, 'active', '2026-11-11 10:16:47', NULL),
(3, 'revenue_potential', 'Tiềm năng doanh thu tốt', 'Có khả năng đạt mục tiêu vé bán và doanh thu kỳ phát hành.', 3, 'active', '2026-11-11 10:16:47', NULL),
(4, 'strong_franchise', 'Thương hiệu phim có sức hút', 'Thuộc thương hiệu, loạt phim hoặc sở hữu dàn diễn viên nổi bật.', 4, 'active', '2026-11-11 10:16:47', NULL),
