(1, 'AURORA20', 'Thứ Tư rực rỡ - Giảm 20%', 'Đặt vé giữa tuần, tận hưởng giá mềm hơn cho mọi hành trình điện ảnh.', 'Giảm 20% tổng giá trị vé khi đặt trực tuyến tại Aurora Cinema. Ưu đãi lý tưởng cho buổi hẹn giữa tuần cùng bạn bè và gia đình.', 'Áp dụng cho đơn vé từ 100.000đ. Mức giảm tối đa 60.000đ. Không áp dụng đồng thời với ưu đãi khác. Số lượng mã có hạn.', 'ticket', 'all', 'ƯU ĐÃI NỔI BẬT', '#D89718', '', 'percent', 20.00, 100000.00, 60000.00, '2026-10-01 00:00:00', '2026-12-31 23:59:59', 1000, 0, 'active', 1, 10, '2026-10-06 18:46:33', '2026-10-07 01:46:33', NULL, 'percent', NULL, NULL, NULL, 0, 0, 0, 'order', NULL),
(2, 'STUDENT40', 'Đồng giá vé học sinh - sinh viên', 'Vé 2D chỉ từ 40.000đ dành cho thế hệ trẻ yêu điện ảnh.', 'Giảm trực tiếp 40.000đ cho đơn vé hợp lệ. Thành viên có thể sử dụng mã tại bước thanh toán và xuất trình thẻ học sinh, sinh viên khi nhận vé.', 'Áp dụng cho khách hàng học sinh, sinh viên có giấy tờ hợp lệ. Đơn tối thiểu 80.000đ. Không áp dụng ngày lễ và suất đặc biệt.', 'member', 'student', 'HỌC SINH · SINH VIÊN', '#E04F87', '', 'amount', 40000.00, 80000.00, 40000.00, '2026-10-01 00:00:00', '2026-12-20 23:59:59', 600, 0, 'active', 1, 20, '2026-10-06 18:46:33', '2026-10-07 01:46:33', NULL, 'percent', NULL, NULL, NULL, 0, 0, 0, 'order', NULL),
(3, 'COMBO25', 'Combo đôi - Trọn vị phim hay', 'Giảm 25% combo bắp lớn và hai nước khi đặt cùng vé xem phim.', 'Tận hưởng combo bắp nước tiết kiệm dành cho hai người. Nhập mã khi thanh toán đơn có cả vé và sản phẩm F&B.', 'Áp dụng cho đơn từ 200.000đ có sản phẩm F&B. Giảm tối đa 75.000đ. Mỗi tài khoản dùng một lần trong thời gian chương trình.', 'combo', 'all', 'COMBO BÁN CHẠY', '#2B8D78', '', 'percent', 25.00, 200000.00, 75000.00, '2026-10-05 00:00:00', '2026-11-30 23:59:59', 800, 0, 'active', 1, 30, '2026-10-06 18:46:33', '2026-10-07 01:46:33', NULL, 'percent', NULL, NULL, NULL, 0, 0, 0, 'order', NULL),
(4, 'MEMBER50', 'Đặc quyền thành viên Aurora', 'Nhận ngay 50.000đ cho lần đặt vé tiếp theo của thành viên.', 'Quà tặng tri ân dành cho thành viên Aurora đã đăng nhập. Mã được áp dụng trực tiếp tại bước thanh toán trực tuyến.', 'Chỉ áp dụng cho tài khoản thành viên. Đơn tối thiểu 180.000đ. Không quy đổi thành tiền mặt và không cộng dồn ưu đãi.', 'member', 'member', 'AURORA REWARDS', '#6E56CF', '', 'amount', 50000.00, 180000.00, 50000.00, '2026-10-01 00:00:00', '2026-12-31 23:59:59', 500, 0, 'active', 0, 40, '2026-10-06 18:46:33', '2026-10-07 01:46:33', NULL, 'percent', NULL, NULL, NULL, 0, 0, 0, 'order', NULL),
(5, 'IMAX15', 'Đắm chìm IMAX - Giảm 15%', 'Nâng cấp trải nghiệm màn ảnh lớn với mức giá hấp dẫn hơn.', 'Giảm 15% cho đơn vé có suất chiếu định dạng IMAX tại các cụm rạp Aurora hỗ trợ.', 'Áp dụng cho đơn từ 250.000đ. Mức giảm tối đa 80.000đ. Không áp dụng cùng voucher khác.', 'experience', 'all', 'IMAX EXPERIENCE', '#2475B9', '', 'percent', 15.00, 250000.00, 80000.00, '2026-10-10 00:00:00', '2026-12-15 23:59:59', 400, 0, 'active', 0, 50, '2026-10-06 18:46:33', '2026-10-07 01:46:33', NULL, 'percent', NULL, NULL, NULL, 0, 0, 0, 'order', NULL),
(6, 'FAMILY60', 'Cuối tuần gia đình - Giảm 60K', 'Thêm niềm vui cho cả nhà với ưu đãi đặt vé nhóm cuối tuần.', 'Giảm 60.000đ cho đơn vé gia đình hoặc nhóm bạn có giá trị từ 300.000đ.', 'Áp dụng cho đơn từ 300.000đ. Mỗi tài khoản được sử dụng tối đa một lần. Số lượng có hạn.', 'ticket', 'family', 'CUỐI TUẦN VUI VẺ', '#C65C3B', '', 'amount', 60000.00, 300000.00, 60000.00, '2026-10-01 00:00:00', '2026-11-30 23:59:59', 350, 0, 'active', 0, 60, '2026-10-06 18:46:33', '2026-10-07 01:46:33', NULL, 'percent', NULL, NULL, NULL, 0, 0, 0, 'order', NULL);
