-- Communication group tables added while merging the shared aurora_db dump.
CREATE TABLE IF NOT EXISTS `aurora_chat_groups` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(80) NOT NULL,
  `description` varchar(240) DEFAULT NULL,
  `created_by_system` varchar(8) NOT NULL,
  `created_by_user_id` bigint(20) UNSIGNED NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

CREATE TABLE IF NOT EXISTS `aurora_chat_group_members` (
  `group_id` bigint(20) UNSIGNED NOT NULL,
  `member_system` varchar(8) NOT NULL,
  `member_user_id` bigint(20) UNSIGNED NOT NULL,
  `member_role` varchar(16) NOT NULL DEFAULT 'member',
  `joined_at` datetime NOT NULL,
  `left_at` datetime DEFAULT NULL,
  PRIMARY KEY (`group_id`,`member_system`,`member_user_id`),
  KEY `idx_group_member` (`member_system`,`member_user_id`,`left_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

CREATE TABLE IF NOT EXISTS `aurora_chat_group_reads` (
  `group_id` bigint(20) UNSIGNED NOT NULL,
  `member_system` varchar(8) NOT NULL,
  `member_user_id` bigint(20) UNSIGNED NOT NULL,
  `last_read_message_id` bigint(20) UNSIGNED NOT NULL DEFAULT 0,
  `read_at` datetime NOT NULL,
  PRIMARY KEY (`group_id`,`member_system`,`member_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
